'use strict';
function main(){
var parts=[['shell',1.2],['ballistic panels',2.4],['plates',3.1],['electronics',0.8]];
var tot=0;for(var i=0;i<parts.length;i++){tot+=parts[i][1];}
return {components:parts, total_kg:Math.round(tot*100)/100, budget_kg:12};
}
